WITH session_stats AS (SELECT session_id, COUNT(DISTINCT duration_sec) AS unique_event_types, ROUND((100 * SUM(CASE WHEN page = '/search' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_search FROM web_events GROUP BY session_id) SELECT s.device, ss.unique_event_types, ss.pct_search FROM sessions s INNER JOIN session_stats ss ON s.id = ss.session_id WHERE ss.pct_search >= 33 ORDER BY s.device;
